values (md5('00000000-0000-4000-8000-000000000001:dj:nir-rozenberg')::uuid, '00000000-0000-4000-8000-000000000001', 'Nir Rozenberg', 'nir-rozenberg', '“Every event is a challenge – to make each and every person dance, and create an atmosphere that the audience will never experience again in their lives.”

After 18 years of experience in making people dance for long hours… even while sleeping, he can find the unique rhythm that will make your event unforgettable.

He’s an expert in a variety of different types of music, but his greatest specialty is conveying emotions and creating a vibe through music alone, and in his opinion, if the most unique and unforgettable experience you have had ever experienced in your life is not an event, you haven’t had the right person on the music.', array['18 years experience','Multi-genre','Emotional moments']::text[], '/djs/nir-rozenberg.webp', '/djs/nir-rozenberg-logo.svg', '{"instagram":"https://instagram.com/rozenberg__n?igshid=YmMyMTA2M2Y=","soundcloud":"https://soundcloud.app.goo.gl/G7RZUMeSY3QDNdcJ6"}'::jsonb, 'dj', true, 6, false)
