values (md5('00000000-0000-4000-8000-000000000001:dj:dalit-rechester')::uuid, '00000000-0000-4000-8000-000000000001', 'Dalit Rechester', 'dalit-rechester', 'The radio was her world and it let her expand herknowledge and understanding of music. She studied music to a depth understanding.

With great intelligence and sensitivity she creates a deep bond between her and the audience. She calms you down on rush hour with great soothing music on the radio, and later on at night she makes you move like there’s no tomorrow.

Put her on stage and let her launch her musical fireworks.', array['Radio','Deep music knowledge']::text[], '/djs/dalit-rechester.webp', '/djs/dalit-rechester-logo.svg', '{"instagram":"https://www.instagram.com/dalitrechester/","youtube":"https://www.youtube.com/user/glgltzgossipgirl","soundcloud":"https://soundcloud.com/dalit-rechester"}'::jsonb, 'dj', true, 11, false)
